[
    {
        "title": "读题找数",
        "description": "全班有 $45$ 人，男生 $20$ 人，女生 $25$ 人。先把已知数据记清楚。",
        "bubbleText": "先别急着算，把“总数、男生数、女生数”分清楚，后面就不会乱。",
        "bubblePos": {
            "x": 150,
            "y": 86
        }
    },
    {
        "title": "求男生概率",
        "description": "随机选一名学生，选中男生的概率 = $\\frac{男生人数}{总人数} = \\frac{20}{45} = \\frac{4}{9}$。",
        "bubbleText": "随机抽人时，每个人机会一样，所以“男生人数 ÷ 总人数”就是概率。",
        "bubblePos": {
            "x": 520,
            "y": 98
        }
    },
    {
        "title": "画出比例",
        "description": "男生占全班的 $\\frac{20}{45}$，所以结果也可以写成约 $0.444$。",
        "bubbleText": "概率就是“占比”，男生越多，这个概率就越大。",
        "bubblePos": {
            "x": 560,
            "y": 246
        }
    },
    {
        "title": "先求总身高",
        "description": "全班总身高是 $45\\times160=7200$ 厘米；男生总身高是 $20\\times165=3300$ 厘米。",
        "bubbleText": "平均数题常用“总量 = 平均数 × 人数”，先把总身高算出来。",
        "bubblePos": {
            "x": 145,
            "y": 352
        }
    },
    {
        "title": "求女生总身高",
        "description": "女生总身高 = $7200-3300=3900$ 厘米。",
        "bubbleText": "全班总身高里扣掉男生那一份，剩下的就是女生总身高。",
        "bubblePos": {
            "x": 470,
            "y": 382
        }
    },
    {
        "title": "求女生平均",
        "description": "女生平均身高 = $3900\\div25=156$ 厘米。",
        "bubbleText": "平均身高还是“总身高 ÷ 人数”，把女生总身高平均分给 25 人。",
        "bubblePos": {
            "x": 470,
            "y": 445
        }
    },
    {
        "title": "答案验证",
        "description": "检查：$20\\div45=4/9$；$25\\times156=3900$，与女生总身高一致，所以答案正确。",
        "bubbleText": "回头验一下，概率和平均身高都对得上，说明我们算对啦。",
        "bubblePos": {
            "x": 260,
            "y": 528
        }
    }
]
